WITH cleaned AS (SELECT *, units * revenue AS revenue_per_unit FROM store_sales WHERE sale_date >= DATE '2023-05-07') SELECT CASE WHEN revenue_per_unit >= 88 THEN 'LARGE' ELSE 'SMALL' END AS revenue_per_unit_tier, COUNT(*) AS num_rows, APPROX_PERCENTILE(revenue, 0.5) AS revenue_p50, MIN(units) AS min_units, STDDEV_SAMP(revenue) AS revenue_stddev, BIT_OR(units) AS units_bit_or FROM cleaned GROUP BY 1;
